def build_default_page_tree(
    title: str,
    category: str,
    theme: str,
    website_type: str = "single",
    selected_pages: List[str] = None,
    logo_url: str = None,
    contact_email: str = None,
    contact_phone: str = None,
    background_style: str = "live",
    theme_mode: str = "dark",
    user_prompt: str = None
) -> Dict[str, Any]:
    colors = get_theme_colors(theme, theme_mode)
    preset = get_dynamic_category_preset(category, title, user_prompt)
    safe_title = title if title else f"NextGen {category}"
    safe_email = contact_email if contact_email else f"contact@{category.lower().replace(' ', '')}.com"
    safe_phone = contact_phone if contact_phone else "+1 (800) 555-0199"

    pages_list = selected_pages if selected_pages else ["Home", "About Us", "Services", "Contact Us"]
    if "Home" not in pages_list:
        pages_list.insert(0, "Home")

    nav_links = []
    if website_type == "multi":
        for p in pages_list:
            href_val = "index.html" if p == "Home" else f"{p.lower().replace(' ', '_')}.html"
            nav_links.append({"label": p, "href": href_val})
    else:
        nav_links = [
            {"label": "Home", "href": "#home"},
            {"label": "About Us", "href": "#about"},
            {"label": "Services", "href": "#services"},
            {"label": "Features", "href": "#features"},
            {"label": "FAQ", "href": "#faq"},
            {"label": "Contact Us", "href": "#contact"}
        ]

    home_hero = {
        "badge": preset["badge"],
        "headline": preset["headline"],
        "subheadline": preset["subheadline"],
        "primary_cta": "Explore Services",
        "secondary_cta": "Contact Us",
        "hero_image": preset["hero_image"]
    }

    about_section = {
        "section_badge": "Our Story & Vision",
        "section_title": f"About {safe_title}",
        "paragraphs": preset["about_story"],
        "mission_title": "Our Mission",
        "mission": f"To empower our clients in {category} through authentic quality, transparent operations, and continuous innovation.",
        "vision_title": "Our Vision",
        "vision": f"To set new standards of excellence and accessible design across the {category} industry."
    }

    services_section = {
        "section_badge": "Professional Offerings",
        "section_title": "Our Core Services",
        "section_subtitle": f"Tailored solutions designed to meet your specific objectives in {category}.",
        "items": preset["services"]
    }

    home_features = {
        "section_badge": "Key Capabilities",
        "section_title": f"Why Choose {safe_title}",
        "section_subtitle": f"Built with precision and care to deliver high-impact performance in {category}.",
        "items": preset["features"]
    }

    faq_section = {
        "section_title": "Frequently Asked Questions",
        "section_subtitle": "Find clear answers to common inquiries regarding our operations and services.",
        "items": preset["faqs"]
    }

    testimonials_section = {
        "section_title": "What Our Clients Say",
        "section_subtitle": f"Authentic feedback from partners and customers who trust {safe_title}.",
        "items": preset["testimonials"]
    }

    contact_section = {
        "section_badge": "Get In Touch",
        "section_title": "Contact Us",
        "section_subtitle": f"Have questions or want to collaborate? Send a message directly to {safe_title}.",
        "contact_email": safe_email,
        "contact_phone": safe_phone,
        "address": f"100 Innovation Parkway, Suite 400, {category} District",
        "form_title": "Send Us a Direct Message"
    }

    home_sections = {
        "brand_name": safe_title,
        "tagline": f"The Ultimate {category} Platform",
        "logo_url": logo_url or f"https://api.dicebear.com/7.x/identicon/svg?seed={safe_title}",
        "theme": theme,
        "colors": colors,
        "website_type": website_type,
        "background_style": background_style,
        "selected_pages": pages_list,
        "navbar": {
            "brand": safe_title,
            "links": nav_links,
            "cta_button": "Get In Touch"
        },
        "hero": home_hero,
        "about": about_section,
        "services": services_section,
        "features": home_features,
        "faq": faq_section,
        "testimonials": testimonials_section,
        "contact": contact_section,
        "cta": {
            "headline": f"Ready to Connect with {safe_title}?",
            "subheadline": "Reach out today and our dedicated team will respond promptly.",
            "button_text": "Contact Us Now"
        },
        "footer": {
            "brand": safe_title,
            "description": f"Next-generation {category} website platform.",
            "contact_email": safe_email,
            "contact_phone": safe_phone,
            "copyright": f"© 2026 {safe_title}. All rights reserved.",
            "credit": "Website built by BuildMyWebsiteAI"
        }
    }

    if website_type == "multi":
        pages_dict = {}
        for p in pages_list:
            if p == "Home":
                pages_dict["Home"] = {
                    "hero": home_hero,
                    "about": about_section,
                    "services": services_section,
                    "features": home_features
                }
            elif p == "About Us":
                pages_dict["About Us"] = {
                    "hero": {
                        "badge": "💡 Our Story & Values",
                        "headline": f"About {safe_title}",
                        "subheadline": f"Dedicated to delivering authentic quality and innovation in {category}.",
                        "primary_cta": "Contact Us"
                    },
                    "about": about_section
                }
            elif p == "Services" or p == "Services / Features":
                pages_dict["Services"] = {
                    "hero": {
                        "badge": "🛠️ Professional Solutions",
                        "headline": f"Services at {safe_title}",
                        "subheadline": f"Comprehensive, high-quality offerings tailored for your goals.",
                        "primary_cta": "Contact Us"
                    },
                    "services": services_section
                }
            elif p == "Contact Us":
                pages_dict["Contact Us"] = {
                    "hero": {
                        "badge": "📞 Connect With Us",
                        "headline": f"Contact {safe_title}",
                        "subheadline": f"Reach out directly via email at {safe_email} or call {safe_phone}.",
                        "primary_cta": "Send Message"
                    },
                    "contact": contact_section
                }
            else:
                pages_dict[p] = {
                    "hero": {
                        "badge": f"✨ {p}",
                        "headline": f"{p} - {safe_title}",
                        "subheadline": f"Discover more about {p.lower()} with {safe_title}."
                    }
                }
        home_sections["pages"] = pages_dict

    return home_sections

def generate_website_tree(
    title: str,
    category: str,
    theme: str,
    website_type: str = "single",
    selected_pages: List[str] = None,
    logo_url: str = None,
    contact_email: str = None,
    contact_phone: str = None,
    background_style: str = "live",
    theme_mode: str = "dark",
    user_prompt: str = None
) -> Dict[str, Any]:
    return build_default_page_tree(title, category, theme, website_type, selected_pages, logo_url, contact_email, contact_phone, background_style, theme_mode, user_prompt)

def edit_website_tree(current_tree: Dict[str, Any], instruction: str) -> Dict[str, Any]:
    updated = json.loads(json.dumps(current_tree))
    if "headline" in instruction.lower() or "title" in instruction.lower():
        updated["hero"]["headline"] = instruction
    else:
        updated["hero"]["subheadline"] = f"Updated: {instruction}"
    return updated
